WITH not_flagged AS (SELECT s.* FROM products s WHERE EXISTS (SELECT 1 FROM inventory c WHERE c.product_id = s.id AND c.last_restock < s.launch_date)) SELECT DATE_TRUNC('WEEK', launch_date) AS week_start, supplier_id, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list, STDDEV_SAMP(price) AS price_stddev, APPROX_PERCENTILE(price, 0.9) AS price_p90, CORR(price, cost) AS corr_price_cost, SORT_ARRAY(COLLECT_SET(category)) AS category_list FROM not_flagged GROUP BY CUBE (DATE_TRUNC('WEEK', launch_date), supplier_id);
